/*
 * A291628  Numbers k such that 3 is the smallest decimal digit of k^2.
 * https://oeis.org/A291628
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th number k (k>0) such that the smallest decimal
 *            digit of k^2 equals 3. The sequence is generated by incremental
 *            search
 * Range:     u8 n <= 16, u16 n <= 1105, u32 n <= 1880, u64 n <= 1880,
 *            u128 n <= 1880, big any n
 * Helpers:   min_digit_is_three
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/min_digit_is_three.h"

/* Returns the n‑th member of the sequence, 1‑based indexing. */
seq_t a(idx_t n)
{
    static seq_t *cache = NULL;   /* cached sequence values */
    static size_t cache_len = 0;  /* number of cached values */
    static size_t cache_cap = 0;  /* capacity of cache */
    static unsigned long long last_k = 0; /* last examined candidate */

    /* Grow cache until it contains at least n terms. */
    while (cache_len < (size_t)n)
    {
        unsigned long long k = last_k + 1ULL;
        unsigned long long sq = k * k;

        if (min_digit_is_three(sq))
        {
            /* increase capacity if needed */
            if (cache_len == cache_cap)
            {
                size_t new_cap = (cache_cap == 0) ? 8 : cache_cap * 2;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (tmp == NULL)
                    abort(); /* out of memory */
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = (seq_t)k; /* store the term */
        }
        last_k = k;
    }

    return cache[(size_t)n - 1];
}
